import{j as e}from"./blog-pages-Br50gGHk.js";import{P as i}from"./compare-pages-DdHzJJD8.js";const r=[{factor:"Doha / Ras Laffan asset profile",atlantis:"QatarEnergy LNG (the world&rsquo;s largest LNG producer) at Ras Laffan Industrial City: 14 existing trains (~77 MTPA) plus the North Field Expansion (NFE: 4 trains +32 MTPA, on-stream 2026&ndash;2028) and North Field South (NFS: 2 trains +16 MTPA, on-stream 2027&ndash;2028), bringing total nameplate to ~126 MTPA",competitor:"—"},{factor:"Operator and JV partners",atlantis:"QatarEnergy with TotalEnergies, ExxonMobil, Shell, ConocoPhillips, Eni, Sinopec, CNPC as NFE/NFS JV partners. Operated through QatarEnergy LNG and its subsidiaries (formerly Qatargas / RasGas).",competitor:"—"},{factor:"Damage mechanism stack",atlantis:"Brittle fracture at -162&deg;C, 9% Ni weld defects, perlite settlement, BOG line CUI, jetty splash-zone marine corrosion (Persian Gulf high humidity + salt), thermal fatigue from loading-cycle severity (peak summer cargo schedules)",competitor:"—"},{factor:"Regulatory regime",atlantis:"OGAW (Office of Energy Affairs Qatar) for downstream regulation, QatarEnergy internal standards (often more stringent than international baseline), API 625 / API 620 Appendix Q / EN 14620 / NFPA 59A / BS 7777 cryogenic codes",competitor:"—"},{factor:"ROI typical (Ras Laffan train)",atlantis:"$5M&ndash;$15M/yr per train &mdash; driven by out-of-service inspection deferral on $300M+ tank assets and turnaround scope optimisation on $2B+ trains",competitor:"—"},{factor:"Implementation per train",atlantis:"12&ndash;18 weeks first train + first tank; 4&ndash;6 weeks per subsequent train. Coexistence with existing QatarEnergy SAP / PI / Maximo landscape.",competitor:"—"}],a=[{question:"Why is Ras Laffan / QatarEnergy a unique digital twin opportunity?",answer:"QatarEnergy at Ras Laffan operates the world&rsquo;s largest LNG production complex by a wide margin. Existing trains total ~77 MTPA. The North Field Expansion (NFE, +32 MTPA across 4 trains) is in advanced construction with first cargo targeted 2026, followed by North Field South (NFS, +16 MTPA across 2 trains, first cargo 2027&ndash;2028). When NFE+NFS are fully online by 2028, Ras Laffan will run ~126 MTPA, by far the world&rsquo;s largest single-site LNG production complex. The integrity programme at this scale &mdash; tens of cryogenic storage tanks, hundreds of cryogenic piping circuits, marine jetties handling the largest LNG carriers ever built, and the integrated GTL (Pearl GTL) and condensate processing complex &mdash; demands a digital-twin-native approach."},{question:"How does Atlantis fit with QatarEnergy&rsquo;s existing integrity tools?",answer:"QatarEnergy and its operating subsidiaries (formerly Qatargas, RasGas; now merged into QatarEnergy LNG) run a deeply customised stack of SAP PM, AVEVA PI (extensive historian footprint), IBM Maximo, plus in-house tools for cryogenic integrity. Atlantis is built to coexist: SAP PM integration via standard BAPIs, AVEVA PI via OPC-UA or PI Web API, Maximo via REST. The Atlantis differentiator is the daily inspector and integrity-engineer workflow &mdash; CML thickness capture, 9% Ni weld map maintenance, API 579 FFS, API 581 RBI, and the 3D twin &mdash; that plugs into the existing landscape rather than displacing it."},{question:"How is 9% Ni cryogenic weld inspection different at Ras Laffan scale?",answer:"9% Ni steel (ASTM A553 Type I) is the workhorse material for LNG inner tank shells, cryogenic piping, and certain heat-exchanger components. Ras Laffan&rsquo;s 14 existing trains plus the 6 NFE/NFS trains under construction means an inspection programme spanning tens of cryogenic storage tanks (typically 165,000&ndash;220,000 m&sup3; full-containment) and hundreds of cryogenic piping runs. Each 9% Ni butt weld is registered as a discrete object in the Atlantis twin: weld number, joint type, base-metal heat numbers, welder ID, WPS reference, PAUT scan file, RT film, and code acceptance status against API 625 / EN 14620 / BS 7777. Reliable digital traceability of construction-vintage weld records (some Qatargas Train 1-3 records go back to 1996&ndash;2002) into the twin is the highest single-day deliverable."},{question:"What about the out-of-service tank inspection workflow for QatarEnergy tanks?",answer:"API 625 (LNG storage tanks) plus the QatarEnergy internal standards mandate periodic out-of-service inspection &mdash; typically every 8&ndash;10 years per tank, with each inspection costing $5M&ndash;$15M and removing a tank from service for 8&ndash;14 weeks. Atlantis Digital Twin builds the evidence stack supporting inspection-interval extension applications: every CML reading, every AET (Acoustic Emission Testing) campaign result, every PAUT 9% Ni weld scan, every perlite-settlement survey, every shell-corrosion-rate trend, every API 579 Fitness-for-Service result, plus the operating-severity tags from PI (inner tank temperature, BOG composition, ambient temperature for thermal-fatigue cycling). With this evidence pack, QatarEnergy can submit for OGAW review with full audit traceability, and 2&ndash;4 year inspection-interval extensions are realistic for mature programmes &mdash; saving $1.5M&ndash;$6M per deferred inspection per tank."},{question:"How does the North Field Expansion construction integration work?",answer:"NFE (4 new trains, +32 MTPA, on-stream 2026&ndash;2028) and NFS (2 new trains, +16 MTPA, on-stream 2027&ndash;2028) are in active construction by the JCC-CTJV (Chiyoda, Technip Energies, Shimizu, KENTZ JV). The Atlantis greenfield deployment model captures construction-vintage records as they are generated: every 9% Ni butt weld with PAUT scan, every CML location with baseline thickness, every cryogenic piping pressure-test record, every tank construction radiograph, all geo-referenced on the 3D twin from day one. Operators who build the digital twin during construction (rather than retrofitting from paper records) eliminate 6&ndash;18 months of post-startup data backfill effort."}];function l(){const n={"@context":"https://schema.org","@graph":[{"@type":"Article",headline:"Digital Twin for QatarEnergy Ras Laffan LNG: World&rsquo;s Largest LNG Complex [2026]",datePublished:"2026-05-25",dateModified:"2026-05-25",author:{"@type":"Person",name:"Anoop Rayavarapu"},publisher:{"@type":"Organization",name:"Atlantis NDT"},mainEntityOfPage:{"@type":"WebPage","@id":"https://atlantisndt.com/digital-twins/lng-terminal-doha"}},{"@type":"FAQPage",mainEntity:a.map(t=>({"@type":"Question",name:t.question,acceptedAnswer:{"@type":"Answer",text:t.answer}}))}]};return e.jsx(i,{title:"Digital Twin for QatarEnergy Ras Laffan LNG (Doha): 126 MTPA Scale [2026]",description:"QatarEnergy Ras Laffan LNG digital twin: 9% Ni weld inspection across 14 + 6 NFE/NFS trains, API 625 tank integrity, BOG management, Persian Gulf marine CUI. Out-of-service tank deferral $1.5M-$6M per tank.",canonical:"https://atlantisndt.com/digital-twins/lng-terminal-doha",eyebrow:"Use Case · Location",h1:"Atlantis Digital Twin for QatarEnergy Ras Laffan (Doha): 9% Ni Welds to 126 MTPA Integrity [2026]",intro:"QatarEnergy at Ras Laffan runs the world’s largest LNG complex — 14 trains (~77 MTPA) today, expanding to ~126 MTPA with the North Field Expansion (NFE +32 MTPA, 2026–2028) and North Field South (NFS +16 MTPA, 2027–2028). Atlantis Digital Twin manages 9% Ni weld inspection, API 625 tank fitness-for-service, BOG line CUI, and Persian Gulf marine jetty integrity for QatarEnergy, TotalEnergies, ExxonMobil, Shell, ConocoPhillips, Eni, Sinopec, and CNPC JV partners.",heroGradient:"from-cyan-700 to-blue-900",competitorLabel:"Doha / Ras Laffan Specifics",compareRows:r,faqs:a,related:[{href:"/digital-twins/lng-terminal",title:"LNG Terminal Use Case",blurb:"Asset-class deep-dive."},{href:"/digital-twin-doha",title:"Doha (Location)",blurb:"Full city DT coverage page."},{href:"/digital-twin-qatar",title:"Qatar Country Coverage",blurb:"Pan-Qatar DT programmes."},{href:"/digital-twins/petrochemical-complex",title:"Petrochemical Complex",blurb:"Adjacent &mdash; Pearl GTL and condensate."},{href:"/contact",title:"Book a Ras Laffan Demo",blurb:"Bring one train&rsquo;s 9% Ni weld map. 30-minute demo."}],ctaTitle:"See Ras Laffan as a Live Cryogenic Integrity Twin",ctaSubtitle:"Bring one train’s weld map and one tank’s out-of-service inspection record. We’ll have it running as an Atlantis twin in a 30-minute demo on a Sunday.",structuredData:n,bodyChildren:e.jsxs(e.Fragment,{children:[e.jsx("h2",{children:"Why QatarEnergy at Ras Laffan is the world’s largest LNG digital twin opportunity"}),e.jsx("p",{children:"QatarEnergy operates the world’s largest LNG production complex at Ras Laffan Industrial City, ~80 km north of Doha. Existing capacity spans 14 trains totalling ~77 MTPA, originally built by Qatargas and RasGas (subsequently merged into QatarEnergy LNG). The North Field Expansion (NFE) adds 4 new trains and ~32 MTPA, with first cargo targeted 2026 and full ramp by 2028. The North Field South (NFS) project adds another 2 trains and ~16 MTPA, with first cargo targeted 2027–2028. By 2028 total Ras Laffan production capacity reaches ~126 MTPA — more than double the next-largest LNG complex globally. JV partners on NFE/NFS include TotalEnergies, ExxonMobil, Shell, ConocoPhillips, Eni, Sinopec, and CNPC, each contributing share of capacity off-take."}),e.jsx("h2",{children:"The Ras Laffan cryogenic damage-mechanism stack"}),e.jsxs("ul",{children:[e.jsxs("li",{children:[e.jsx("strong",{children:"Brittle fracture at -162°C."})," 9% Ni inner tank shells, stainless steel piping, and aluminium-alloy cryogenic exchangers all require brittle-fracture screening per ASME Section VIII Div. 2 Part 3 and API 579 Part 3, with PAUT confirming weld and base-metal integrity."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"9% Ni weld defects."})," ASTM A553 Type I welds are inspected per API 625 / EN 14620 / BS 7777. Each weld has a complete digital record in the Atlantis twin: heat numbers, welder ID, WPS, PAUT scan file, RT film, code acceptance."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Perlite settlement in tank annular space."})," Tracked via NDE surveys and aerial photogrammetry; overlay on the 3D tank model in the twin."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"BOG line CUI."})," BOG (boil-off gas) handling piping near-ambient externally but heavily insulated. Pulsed eddy current and digital RT scan archiving feed the CUI risk overlay per API 583."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Persian Gulf marine jetty corrosion."})," Jetty piles, loading arms, and quick-connect couplings face severe external corrosion from high-humidity salt-laden air plus the Persian Gulf summer temperature regime. Annual UT thickness grids on jetty splash-zone components are the norm."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Thermal fatigue from loading-cycle severity."})," Ras Laffan handles peak-summer cargo schedules with extreme thermal cycling between cooldown, loading, hold, and warm-up. API 579 Part 14 fatigue assessment is core to the integrity plan."]})]}),e.jsx("h2",{children:"The 9% Ni weld inspection workflow at NFE/NFS construction scale"}),e.jsx("p",{children:"Each NFE train carries ~3,000–6,000 9% Ni butt welds across the cryogenic piping system and the LNG inner-tank shell. Multiply by 4 NFE trains plus 2 NFS trains plus the 14 existing trains — the cumulative 9% Ni weld inventory at Ras Laffan exceeds 100,000 weld map entries. Atlantis registers every weld as a discrete digital object: weld number, joint type (butt / fillet / corner), base-metal heat numbers (both sides), welder ID, qualification record (PQR/WPQR), WPS reference, PAUT scan file (in native Olympus OmniScan / Eddyfi M2M / Sonatest format), RT film if applicable, MT/PT records, and the code acceptance status against API 625 / EN 14620 / BS 7777. The 3D twin geo-references every weld on the tank shell or piping run so integrity engineers can click any weld and immediately retrieve the full NDE history."}),e.jsx("h2",{children:"Tank out-of-service inspection deferral — the highest-value workflow"}),e.jsx("p",{children:"A Ras Laffan full-containment LNG storage tank (typically 165,000–220,000 m³ per tank) is a $300M+ capital asset with a 60-year design life. Out-of-service inspection on a single tank costs $5M–$15M and removes the tank from service for 8–14 weeks. With 30+ tanks across Ras Laffan post-NFE/NFS, the inspection economics dominate the integrity programme. Atlantis Digital Twin assembles the evidence pack supporting inspection-interval extension applications: every CML thickness reading on shell and bottom, every AET acoustic emission campaign result, every PAUT weld scan, every perlite-settlement survey, every shell-corrosion-rate trend, every API 579 FFS result, plus operating-severity tags from PI. With this evidence pack, QatarEnergy LNG can submit for OGAW (Office of Energy Affairs Qatar) review with full audit traceability. Mature programmes achieve 2–4 year inspection-interval extensions, saving $1.5M–$6M per deferred inspection per tank — tens of millions of dollars per decade across the Ras Laffan tank fleet."}),e.jsx("h2",{children:"BOG management and the Pearl GTL integration"}),e.jsx("p",{children:"Ras Laffan also hosts the Pearl GTL complex (Shell-operated, ~140,000 bpd of GTL products), the world’s largest gas-to-liquids facility. The integrated cryogenic + GTL + condensate complex makes the digital twin scope broader than a pure LNG terminal: cryogenic LNG service, ambient sour service in the condensate train, hydroprocessing in the Pearl GTL hydrocracker, and the marine jetty handling both LNG carriers and condensate tankers. Atlantis Digital Twin handles the full mix from a single 3D model, with damage-mechanism templates and code-base switching by asset class."}),e.jsx("h2",{children:"Implementation in the QatarEnergy ecosystem"}),e.jsx("p",{children:"First train + first tank live in 12–18 weeks. Subsequent trains 4–6 weeks each. Coexistence with the existing QatarEnergy SAP PM + AVEVA PI + Maximo stack is the norm; integration via standard BAPIs (SAP), PI Web API (AVEVA), and REST (Maximo). For greenfield NFE/NFS deployment, capturing construction-vintage data as it’s generated (rather than retrofitting from paper records after startup) eliminates 6–18 months of post-startup data backfill effort. QatarEnergy LNG inspection contractors integrating with Atlantis include Bureau Veritas, Lloyd’s Register, DNV, ABS, TUV, Applus+ RTD, Stork, Mistras, and the in-house QatarEnergy inspection department."})]})})}export{l as default};
